const seen = new Set();
return $input.all().map(item => {
 const e = item.json;
 if (typeof e.run_id !== 'string' || !e.run_id || !Number.isInteger(e.issue_number) || e.issue_number < 1 || !['done','question','stuck'].includes(e.status)) return {json:{status:'rejected',reason:'invalid_runner_event'}};
 if (seen.has(e.run_id)) return {json:{run_id:e.run_id,status:'duplicate'}};
 seen.add(e.run_id);
 return {json:{run_id:e.run_id,issue_number:e.issue_number,status:'accepted'}};
});
